// Structured character-library v3 fields remain editable and round-trip intact.
const beforeCharacterDetails=characters;
characters=function(){beforeCharacterDetails();const c=data.characters[ci];if(!c)return;const settings=document.querySelector('#charPrompt')?.closest('.card');if(!settings)return;
  const negative=document.createElement('label');negative.textContent='负面提示词（避免出现的内容）';const negativeInput=document.createElement('textarea');negativeInput.rows=4;negativeInput.value=c.negativePrompt||c.generation?.negative_prompt||'';negative.append(negativeInput);document.querySelector('#charPrompt').closest('label').after(negative);negativeInput.oninput=()=>{c.negativePrompt=negativeInput.value;c.generation??={};c.generation.negative_prompt=negativeInput.value;save()};
  const positiveInput=document.querySelector('#charPrompt'),previousInput=positiveInput.oninput;positiveInput.oninput=e=>{previousInput?.(e);c.generation??={};c.generation.positive_prompt=c.prompt;save()};
  const details=document.createElement('div');details.className='card';details.style.cssText='grid-column:1/-1';const title=document.createElement('h3');title.textContent='角色详细设定';title.style.marginTop='0';details.append(title);const hint=document.createElement('p');hint.className='subtle';hint.textContent='结构化设定随项目保存与导出。参考图路径只记录位置，实际图片仍需另行接入。';details.append(hint);
  const grid=document.createElement('div');grid.className='stage-grid';details.append(grid);
  for(const [property,label] of [['appearance','外貌与服装'],['personality','性格与情感'],['voice','声音设定'],['animation','动作设定'],['animation_rules','动作规则'],['negative_constraints','负面约束'],['consistency_rules','角色一致性约束'],['reference_images','参考图片路径']]){const group=document.createElement('details');group.style.cssText='padding:13px;border:1px solid var(--line);border-radius:7px;align-self:start';const summary=document.createElement('summary');summary.textContent=label;summary.style.cursor='pointer';const editor=document.createElement('textarea');editor.rows=8;editor.setAttribute('aria-label',label+' JSON');editor.value=JSON.stringify(c[property]||(['animation_rules','negative_constraints'].includes(property)?[]:{}),null,2);const status=document.createElement('p');status.className='subtle';editor.oninput=()=>{try{const value=JSON.parse(editor.value);if(!value||typeof value!=='object')throw Error('需要 JSON 对象或数组');c[property]=value;save();status.textContent='已保存';editor.setCustomValidity('')}catch{status.textContent='JSON 格式未完成，暂未保存；上次有效内容保留。';editor.setCustomValidity('请填写有效的 JSON 对象')}};group.append(summary,editor,status);grid.append(group)}
  if(c.story_function){const story=document.createElement('p');story.textContent='剧情作用：'+c.story_function;details.append(story)}
  document.querySelector('#panel .editor')?.append(details);
};
// Read a compact summary instead of displaying serialized appearance JSON.
const detailOverview=overview;
function summaryValues(value){if(value==null)return [];if(Array.isArray(value))return value.flatMap(summaryValues);if(typeof value==='object')return Object.values(value).flatMap(summaryValues);return typeof value==='string'?[value]:[];}
overview=function(){detailOverview();for(const c of data.characters){if(!c.prompt)c.prompt=c.generation?.positive_prompt||c.prompt_anchor_zh||'';if(!c.negativePrompt)c.negativePrompt=c.generation?.negative_prompt||(Array.isArray(c.negative_constraints)?c.negative_constraints.join('\n'):'');if(c.appearance&&(!c.description||c.description.startsWith('{')||c.file_schema_updated!==true)){const traits=Array.isArray(c.personality)?c.personality:c.personality?.traits;c.description=[...summaryValues(c.appearance),...(traits||[]),c.story_arc||c.character_arc].filter(Boolean).join('；');c.file_schema_updated=true;}}};
const renderImportedCharacters=characters;
characters=function(){renderImportedCharacters();const c=data.characters[ci];if(!c)return;const preview=document.querySelector('#panel .artboard');if(preview&&(c.character_id||c.reference_images)&&!(c.versions?.length)&&c.view!=='multi'){preview.replaceChildren();const empty=document.createElement('div');empty.className='empty-stage';const title=document.createElement('h3');title.textContent=c.name+' · 尚未生成正面图';const hint=document.createElement('p');hint.textContent='角色设定已导入，参考路径暂为记录。';empty.append(title,hint);preview.append(empty)}};
render();save();
